import{_ as a,o as r,c as d,a2 as l}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"跨位面探索紀元","description":"","frontmatter":{},"headers":[],"relativePath":"ja/78-跨位面探索纪元.md","filePath":"ja/78-跨位面探索纪元.md"}'),e={name:"ja/78-跨位面探索纪元.md"};function o(i,t,n,h,s,g){return r(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="跨位面探索紀元" tabindex="-1">跨位面探索紀元 <a class="header-anchor" href="#跨位面探索紀元" aria-label="Permalink to &quot;跨位面探索紀元&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>78</td></tr><tr><td>所属モジュール</td><td>歴史紀元と重大事件</td></tr><tr><td>コアキーワード</td><td>跨位面探索、位面大発見、考古協定、先観測後干渉、星間共生</td></tr></tbody></table><h2 id="第一節-跨位面探索紀元の開啓条件" tabindex="-1">第一節 跨位面探索紀元の開啓条件 <a class="header-anchor" href="#第一節-跨位面探索紀元の開啓条件" aria-label="Permalink to &quot;第一節 跨位面探索紀元の開啓条件&quot;">​</a></h2><p>跨位面探索紀元は万族共和成立後に開啓された新紀元であり、四階段昇維経路における「意識進化」から「星間共生」への移行段階に対応する。この紀元の開啓には三つの条件が同時に成熟する必要がある:</p><ul><li><strong>技術条件</strong>: 空間法理技術が「源空」の境地に達し、跨位面チャネルの安定的な開啓が可能になる; 複製鏡と隔離空間技術が成熟し、低汚染探索の技術的保障を提供する</li><li><strong>制度条件</strong>: 万族共和が成立し、統一された跨位面探索政策と考古協定の制定が完了する</li><li><strong>動力条件</strong>: 既知位面の昇維作業が秩序立って推進され、文明が未知位面へ拡張する能力と意欲を持つ</li></ul><p>これら三つの条件が同時に成熟したとき、万族共和は正式に「大探索計画」の起動を宣言し、跨位面探索紀元がここに開啓される。</p><h2 id="第二節-跨位面探索の基本原則" tabindex="-1">第二節 跨位面探索の基本原則 <a class="header-anchor" href="#第二節-跨位面探索の基本原則" aria-label="Permalink to &quot;第二節 跨位面探索の基本原則&quot;">​</a></h2><p>跨位面探索は以下の基本原則を厳格に遵守し、これらの原則は『跨位面探索基本法』に書き込まれている:</p><table tabindex="0"><thead><tr><th>原則</th><th>内包</th></tr></thead><tbody><tr><td>先観測後有限干渉</td><td>未知位面に対してまず受動的観測を行い、十分な理解の後に限定的な接触と干渉を行う</td></tr><tr><td>低汚染探索</td><td>複製鏡+隔離空間の考古方案を採用し、知識のみを回伝し、物質と生命を持ち込み・持ち出ししない</td></tr><tr><td>原生文明保護</td><td>原生文明が存在する位面に対して、その自主発展権を尊重し、共生制度を強制的に吹き込んではならない</td></tr><tr><td>資源共有</td><td>探索で発見された知識と資源は全文明の共有に帰し、いかなる組織も探索成果を独占してはならない</td></tr><tr><td>安全優先</td><td>探索過程における安全は常に首位に置かれ、高危険位面の探索は厳格なリスク評価を経なければならない</td></tr></tbody></table><h2 id="第三節-探索の技術手段" tabindex="-1">第三節 探索の技術手段 <a class="header-anchor" href="#第三節-探索の技術手段" aria-label="Permalink to &quot;第三節 探索の技術手段&quot;">​</a></h2><p>跨位面探索は共生文明の複数のコア技術を総合的に運用している:</p><ol><li><strong>位面スキャン技術</strong>: 空間法理知覚モジュールに基づく遠隔位面スキャン、標的位面に接触することなくその基本情報（空間構造、エネルギーレベル、生命徴候など）を取得可能</li><li><strong>複製鏡考古方案</strong>: 標的位面に対して高精度な鏡像複製を行い、隔離空間内で鏡像複製に対して深入りした研究を行い、知識のみを回伝</li><li><strong>跨位面通信プローブ</strong>: 微型の法則通信装置、標的位面に送入して近距離観測を行うことができ、データは跨位面通信ネットワークを通じてリアルタイムで回伝</li><li><strong>意識域知覚</strong>: 高階修錬者が意識域を通じて標的位面に対して遠隔知覚を行い、スキャン技術では捕捉できない意識層面の情報を取得</li><li><strong>アンカー遠隔配置</strong>: 安全レベルの高い位面に対して、臨時アンカーを遠隔配置し、安定した接続チャネルを構築可能</li></ol><h2 id="第四節-探索の組織と実施" tabindex="-1">第四節 探索の組織と実施 <a class="header-anchor" href="#第四節-探索の組織と実施" aria-label="Permalink to &quot;第四節 探索の組織と実施&quot;">​</a></h2><p>跨位面探索は万族共和の「跨位面探索局」によって統一的に組織・実施され、「階級探索」のモデルを採用している:</p><table tabindex="0"><thead><tr><th>探索等級</th><th>標的類型</th><th>探索方式</th><th>人員配置</th></tr></thead><tbody><tr><td>一級探索</td><td>無生命の荒廃位面</td><td>遠隔スキャン+複製鏡研究</td><td>技術チーム主体</td></tr><tr><td>二級探索</td><td>低等生命のある位面</td><td>複製鏡考古+限定実地考察</td><td>技術チーム+生物学者</td></tr><tr><td>三級探索</td><td>原生文明のある位面</td><td>先観測後接触、接触協定を厳格遵守</td><td>完全チーム+外交官+倫理観察員</td></tr><tr><td>四級探索</td><td>高危険/未知位面</td><td>隔離空間模擬研究のみ、実地接触禁止</td><td>最高級安全チーム</td></tr></tbody></table><p>各探索プロジェクトは「探索申請—リスク評価—倫理審査—批准実施—過程監視—成果共有」の完全なプロセスを経なければならない。</p><h2 id="第五節-探索紀元の重大発見" tabindex="-1">第五節 探索紀元の重大発見 <a class="header-anchor" href="#第五節-探索紀元の重大発見" aria-label="Permalink to &quot;第五節 探索紀元の重大発見&quot;">​</a></h2><p>跨位面探索紀元が開啓された後、共生文明は一連の重大発見を取得した:</p><ul><li><strong>新種族発見</strong>: 未知位面においてこれまで未知の大量の知恵種族が発見され、万族譜系が大幅に拡張された。これらの新種族は自発的な選択の後、徐々に万族共和に加入した</li><li><strong>新法則発見</strong>: 異なる位面の法則構造には差異が存在し、探索中に多種の新しい法則変異体が発見され、三百套修錬体系の理論基礎が豊かになった</li><li><strong>古文明遺跡</strong>: 前アンカー時代の絶滅文明の複数の遺跡が発見され、複製鏡考古を通じて大量の貴重な歴史知識が取得された</li><li><strong>异位面共生文明</strong>: 一部の位面において独立して共生理念を発展させた原生文明が発見され、アンカー共生文明と空間を越えた思想的共鳴を形成した</li><li><strong>宇宙境界探索</strong>: 探索が徐々に衡元宙の既知の境界に触れ、宇宙全体の構造に対する認識が不断に深化している</li></ul><h2 id="第六節-探索における挑戦と反省" tabindex="-1">第六節 探索における挑戦と反省 <a class="header-anchor" href="#第六節-探索における挑戦と反省" aria-label="Permalink to &quot;第六節 探索における挑戦と反省&quot;">​</a></h2><p>跨位面探索は順風満帆ではなく、過程において挑戦にも遭遇した:</p><ul><li><strong>文化衝突</strong>: 原生文明との接触において文化的誤解と衝突が発生し、接触協定の不断の完善を促した</li><li><strong>探索倫理争議</strong>: 「原生文明に能動的に接触すべきか」について持続的な倫理弁論が存在し、最終的に「能動せず、回避せず、選択を尊重する」という共識が形成された</li><li><strong>安全事故</strong>: 高危険位面探索において隔離空間バリア破損事故が発生した; 深刻な結果は引き起こさなかったが、安全基準の更なる向上を推進した</li><li><strong>資源配分</strong>: 大規模探索には大量の資源消費が必要であり、探索投入と本土民生投入の間のバランスが政治弁論の焦点となった</li></ul><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>跨位面探索紀元はアンカー共生文明の「大航海時代」である。それは文明の視野を既知位面から宇宙全体に拡張し、新世界を発見すると同時に自身に対する理解も深化させた。複製鏡+隔離空間の低汚染探索方案により、共生文明の探索は歴史上の一切の略奪式植民拡張と区別される——私たちが持ち込むのは征服と略奪ではなく、尊重と知識である; 私たちが持ち帰るのは資源と奴隷ではなく、理解と智慧である。探索された位面が十分に多く、アンカーネットワークが十分に密になったとき、星間共生時代の扉がゆっくりと開かれるだろう。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>77-万族共和成立</li><li>79-星間共生時代展望</li><li>84-考古協定綱領</li></ul>',26)])])}const u=a(e,[["render",o]]);export{c as __pageData,u as default};
